const [path,action]=process.argv.slice(2),scope={tenantId:'tenant',applicationId:'app'},provider=new SqliteDataProvider(path),plan=action==='forward'?{fromVersion:0,toVersion:1,transform:value=>({fullName:value.name}),validate:value=>typeof value.fullName==='string'}:{fromVersion:1,targetVersion:0,transform:value=>({name:value.fullName}),validate:value=>typeof value.name==='string'};
